    artists_n_sorted = norm_set(artists)
    query = title + ' ' + ' '.join(artists)

    def res_artists_sorted(r):
        return sorted([norm(a['name']) for a in r.get('artists', []) if a.get('name')])

    for page_index in range(max_pages):
        results = apis.spotify.search_albums(query=query, page_index=page_index, page_limit=page_limit)
        if not results:
            continue
        exact = [
            r for r in results
            if norm(r.get('title','')) == title_n and res_artists_sorted(r) == artists_n_sorted
        ]
        if len(exact) >= 1:
            return exact[0]['album_id'], {'page_index': page_index, 'exact_matches': len(exact)}

    # fallback: exact title only on page 0
    results0 = apis.spotify.search_albums(query=title, page_index=0, page_limit=page_limit)
    if results0:
        exact_title = [r for r in results0 if norm(r.get('title','')) == title_n]
        if len(exact_title) >= 1:
            return exact_title[0]['album_id'], {'page_index': 0, 'fallback_title_only_matches': len(exact_title)}

    return None, {'found': False}

