resolved_song_library=[]
for title, artists in songs_library:
    sid, meta=resolve_song_id(title, artists)
    resolved_song_library.append({'title':title,'artists':artists,'song_id':sid,'meta':meta})

missing_song_library=[r for r in resolved_song_library if r['song_id'] is None]
print('Resolved Song Library: missing', len(missing_song_library))

# --- Resolve album library ---
resolved_album_library=[]
for title, artists in albums_library:
    aid, meta=resolve_album_id(title, artists)
    resolved_album_library.append({'title':title,'artists':artists,'album_id':aid,'meta':meta})

missing_album_library=[r for r in resolved_album_library if r['album_id'] is None]
print('Resolved Album Library: missing', len(missing_album_library))

# --- Resolve playlist songs (ordered) ---
resolved_playlists={}
missing_playlist_entries=[]
for pl_title, entries in playlists.items():
    ids=[]
    entry_details=[]
    for stitle, sartists in entries:
        sid, meta=resolve_song_id(stitle, sartists)
        ids.append(sid)
        entry_details.append({'title':stitle,'artists':sartists,'song_id':sid,'meta':meta})
        if sid is None:
            missing_playlist_entries.append((pl_title, stitle))
    resolved_playlists[pl_title]= {'song_ids': ids, 'entries': entry_details}

print('Resolved Playlists: missing_entries', len(missing_playlist_entries))

# --- Compute deltas for libraries ---
desired_song_ids_library=[r['song_id'] for r in resolved_song_library if r['song_id'] is not None]
desired_album_ids_library=[r['album_id'] for r in resolved_album_library if r['album_id'] is not None]

need_song_add=sorted(set(desired_song_ids_library)-existing_song_ids)
need_album_add=sorted(set(desired_album_ids_library)-existing_album_ids)

print('Delta for library adds', {'songs_to_add': len(need_song_add), 'albums_to_add': len(need_album_add)})

# --- Compute playlist actions ---
playlist_actions=[]
for pl_title, pl_data in resolved_playlists.items():
    pl_title_norm=norm(pl_title)
    existing_ids=sorted(pl_title_to_id.get(pl_title_norm, []))
    if existing_ids:
        # choose first
        target_pl_id=existing_ids[0]
        # fetch existing songs in that playlist
        pl=apis.spotify.show_playlist(playlist_id=target_pl_id, access_token=spotify_token)
        existing_song_ids_in_pl=set([s['id'] if 'id' in s else s.get('song_id') for s in pl.get('songs',[])])
        # order-preserving list of missing song_ids (avoid adding ones already present)
        missing_song_ids=[sid for sid in pl_data['song_ids'] if sid is not None and sid not in existing_song_ids_in_pl]
        action={'playlist_title':pl_title,'playlist_id':target_pl_id,'create':False,'missing_song_ids':missing_song_ids,'expected_song_count':len([x for x in pl_data['song_ids'] if x is not None])}
    else:
        missing_song_ids=[sid for sid in pl_data['song_ids'] if sid is not None]
        action={'playlist_title':pl_title,'playlist_id':None,'create':True,'missing_song_ids':missing_song_ids,'expected_song_count':len(missing_song_ids)}
    playlist_actions.append(action)

create_count=sum(1 for a in playlist_actions if a['create'])
add_song_count=sum(len(a['missing_song_ids']) for a in playlist_actions)
print('Playlist actions summary', {'create_playlists': create_count, 'total_songs_to_add_to_playlists': add_song_count})

# --- Verification prints ---
print('\nSONG LIBRARY VERIFICATION (title -> song_id)')
for r in resolved_song_library:
    print(r['title'], '|', ','.join(r['artists']), '=>', r['song_id'])

print('\nALBUM LIBRARY VERIFICATION (title -> album_id)')
for r in resolved_album_library:
    print(r['title'], '|', ','.join(r['artists']), '=>', r['album_id'])

print('\nPLAYLIST VERIFICATION (playlist | expected_count | song_ids)')
for a in sorted(playlist_actions, key=lambda x: x['playlist_title']):
    ids=a['missing_song_ids']
    print(a['playlist_title'], '|', a['expected_song_count'], '|', ids)
